// gen-terms-variables emits the TypeScript view of the T&C variable registry
// declared in internal/terms/variables.go.
//
//	go run ./cmd/gen-terms-variables -out frontend/src/utils/termsVariables.generated.ts
//
// The generated file is checked in so the frontend build does not need a Go
// toolchain. Re-run whenever you add or rename a variable.
package main

import (
	"flag"
	"fmt"
	"log"
	"os"
	"strings"

	"clientroll/internal/terms"
)

const header = `// Code generated by cmd/gen-terms-variables. DO NOT EDIT.
// Source of truth: internal/terms/variables.go
// Re-run: go generate ./internal/terms/...

export interface TermsVariable {
  key: string;
  label: string;
  desc: string;
}

export const TERMS_VARIABLES: TermsVariable[] = [
`

const footer = `];

export const TERMS_VARIABLE_KEYS: string[] = TERMS_VARIABLES.map(v => v.key);
`

func main() {
	out := flag.String("out", "", "output file path")
	flag.Parse()
	if *out == "" {
		log.Fatal("must pass -out path")
	}

	var b strings.Builder
	b.WriteString(header)
	for _, v := range terms.All {
		fmt.Fprintf(&b, "  { key: %q, label: %q, desc: %q },\n", v.Key, v.Label, v.Desc)
	}
	b.WriteString(footer)

	if err := os.WriteFile(*out, []byte(b.String()), 0o644); err != nil {
		log.Fatalf("write %s: %v", *out, err)
	}
	fmt.Printf("wrote %s (%d variables)\n", *out, len(terms.All))
}
